"use client";

import { useEffect, useMemo, useState } from "react";
import { useRouter } from "next/navigation";
import { lectii } from "../../data/lectii/index";
import { createClient } from "../../lib/supabase/client";

type ProgresLectie = {
  id: string;
  titlu: string;
  finalizata: boolean;
  xp: number;
  modul: number;
  numarLectie: number;
  totalLectiiModul: number;
  href: string;
};

type ProgresSupabase = {
  lesson_id: string;
  completed: boolean;
  xp: number;
};

export default function DashboardPage() {
  const router = useRouter();
  const [supabase] = useState(() => createClient());

  const [nume, setNume] = useState("");
  const [profil, setProfil] = useState("M_mate-info");
  const [progres, setProgres] = useState<ProgresLectie[]>([]);
  const [gata, setGata] = useState(false);
  const [seDeconecteaza, setSeDeconecteaza] = useState(false);

  async function deconectare() {
    setSeDeconecteaza(true);

    const { error } = await supabase.auth.signOut();

    if (error) {
      setSeDeconecteaza(false);
      return;
    }

    localStorage.removeItem("bac-mate-nume");
    localStorage.removeItem("bac-mate-profil-cod");
    localStorage.removeItem("bac-mate-profil-nume");
    localStorage.removeItem(
      "bac-mate-evaluare-initiala-finalizata"
    );

    router.replace("/cont");
    router.refresh();
  }

  useEffect(() => {
    async function incarcaDashboard() {
      const {
        data: { user },
        error: userError,
      } = await supabase.auth.getUser();

      if (userError || !user) {
        router.replace("/cont");
        return;
      }

      const { data: profilSupabase, error: profilError } =
        await supabase
          .from("profiles")
          .select(
            "nume, profil_bac, evaluare_initiala_finalizata"
          )
          .eq("id", user.id)
          .maybeSingle();

      if (profilError) {
        router.replace("/cont");
        return;
      }

      if (!profilSupabase?.nume) {
        router.replace("/date-personale");
        return;
      }

      if (!profilSupabase.profil_bac) {
        router.replace("/profil");
        return;
      }

      if (!profilSupabase.evaluare_initiala_finalizata) {
        router.replace("/evaluare");
        return;
      }

      setNume(profilSupabase.nume);
      setProfil(profilSupabase.profil_bac);

      localStorage.setItem(
        "bac-mate-nume",
        profilSupabase.nume
      );

      localStorage.setItem(
        "bac-mate-profil-cod",
        profilSupabase.profil_bac
      );

      localStorage.setItem(
        "bac-mate-evaluare-initiala-finalizata",
        "da"
      );

      let progresDinSupabase: ProgresSupabase[] = [];

      const { data: progresSalvat, error: progresError } =
        await supabase
          .from("student_progress")
          .select("lesson_id, completed, xp")
          .eq("user_id", user.id);

      if (!progresError && progresSalvat) {
        progresDinSupabase = progresSalvat;
      }

      const progresLectii: ProgresLectie[] = lectii.map(
        (lectie) => {
          const progresCloud = progresDinSupabase.find(
            (item) => item.lesson_id === lectie.id
          );

          const finalizataLocal =
            localStorage.getItem(
              lectie.storageKeyFinalizata
            ) === "da";

          const xpLocal = Number(
            localStorage.getItem(lectie.storageKeyXp) || "0"
          );

          const finalizata =
            progresCloud?.completed ?? finalizataLocal;

          const xp =
            typeof progresCloud?.xp === "number"
              ? progresCloud.xp
              : Number.isNaN(xpLocal)
                ? 0
                : xpLocal;

          if (progresCloud) {
            localStorage.setItem(
              lectie.storageKeyXp,
              String(xp)
            );

            if (finalizata) {
              localStorage.setItem(
                lectie.storageKeyFinalizata,
                "da"
              );
            } else {
              localStorage.removeItem(
                lectie.storageKeyFinalizata
              );
            }
          }

          return {
            id: lectie.id,
            titlu: lectie.titlu,
            finalizata,
            xp,
            modul: lectie.modul,
            numarLectie: lectie.numarLectie,
            totalLectiiModul: lectie.totalLectiiModul,
            href: `/lectii/${lectie.slug}`,
          };
        }
      );

      setProgres(progresLectii);
      setGata(true);
    }

    incarcaDashboard();
  }, [router, supabase]);

  const totalLectii = progres.length;

  const lectiiFinalizate = useMemo(
    () =>
      progres.filter((lectie) => lectie.finalizata)
        .length,
    [progres]
  );

  const xpTotal = useMemo(
    () =>
      progres.reduce(
        (total, lectie) => total + lectie.xp,
        0
      ),
    [progres]
  );

  const procentGeneral =
    totalLectii === 0
      ? 0
      : Math.round(
          (lectiiFinalizate / totalLectii) * 100
        );

  const urmatoareaLectie = useMemo(() => {
    if (progres.length === 0) {
      return null;
    }

    const primaNefinalizata = progres.find(
      (lectie) => !lectie.finalizata
    );

    if (primaNefinalizata) {
      return primaNefinalizata;
    }

    return progres[progres.length - 1];
  }, [progres]);

  const progresPeModule = useMemo(() => {
    const module = new Map<
      number,
      {
        total: number;
        finalizate: number;
      }
    >();

    progres.forEach((lectie) => {
      const modulExistent = module.get(
        lectie.modul
      ) || {
        total: 0,
        finalizate: 0,
      };

      modulExistent.total += 1;

      if (lectie.finalizata) {
        modulExistent.finalizate += 1;
      }

      module.set(lectie.modul, modulExistent);
    });

    return Array.from(module.entries())
      .sort(([a], [b]) => a - b)
      .map(([modul, valori]) => ({
        modul,
        ...valori,
        procent:
          valori.total === 0
            ? 0
            : Math.round(
                (valori.finalizate /
                  valori.total) *
                  100
              ),
      }));
  }, [progres]);

  if (!gata) {
    return (
      <main className="min-h-screen bg-slate-950 text-white">
        <div className="mx-auto max-w-6xl px-6 py-20">
          <p className="text-slate-400">
            Se verifică autentificarea și se încarcă
            progresul...
          </p>
        </div>
      </main>
    );
  }

  return (
    <main className="min-h-screen bg-slate-950 text-white">
      <header className="border-b border-slate-800">
        <div className="mx-auto flex max-w-6xl items-center justify-between px-6 py-5">
          <a
            href="/"
            className="text-xl font-black"
          >
            BAC{" "}
            <span className="text-blue-500">
              MATE
            </span>
          </a>

          <div className="flex items-center gap-3">
            <a
              href="/programa"
              className="rounded-xl border border-slate-700 px-4 py-2 text-sm font-bold text-slate-300 transition hover:bg-slate-900"
            >
              Programa
            </a>

            <div className="rounded-xl bg-blue-500/10 px-4 py-2 text-sm font-bold text-blue-400">
              {profil}
            </div>

            <button
              type="button"
              onClick={deconectare}
              disabled={seDeconecteaza}
              className="rounded-xl border border-red-500/30 bg-red-500/10 px-4 py-2 text-sm font-bold text-red-400 transition hover:bg-red-500/20 disabled:cursor-not-allowed disabled:opacity-50"
            >
              {seDeconecteaza
                ? "Se deconectează..."
                : "Deconectare"}
            </button>
          </div>
        </div>
      </header>

      <div className="mx-auto max-w-6xl px-6 py-12">
        <section>
          <p className="text-sm font-black uppercase tracking-wider text-blue-400">
            Dashboard
          </p>

          <h1 className="mt-3 text-4xl font-black md:text-5xl">
            {nume
              ? `Salut, ${nume} 👋`
              : "Progresul tău la BAC MATE"}
          </h1>

          <p className="mt-4 max-w-3xl text-lg leading-8 text-slate-400">
            Aici vezi ce ai terminat, cât XP ai
            acumulat și care este următoarea lecție
            recomandată.
          </p>
        </section>

        <section className="mt-10 grid gap-5 md:grid-cols-4">
          <div className="rounded-3xl border border-slate-800 bg-slate-900 p-6">
            <p className="text-sm font-bold text-slate-400">
              Progres general
            </p>

            <p className="mt-3 text-4xl font-black">
              {procentGeneral}%
            </p>

            <p className="mt-2 text-sm text-slate-500">
              {lectiiFinalizate} din {totalLectii}{" "}
              lecții construite
            </p>
          </div>

          <div className="rounded-3xl border border-slate-800 bg-slate-900 p-6">
            <p className="text-sm font-bold text-slate-400">
              Lecții finalizate
            </p>

            <p className="mt-3 text-4xl font-black text-emerald-400">
              {lectiiFinalizate}
            </p>

            <p className="mt-2 text-sm text-slate-500">
              Continuă traseul pas cu pas
            </p>
          </div>

          <div className="rounded-3xl border border-slate-800 bg-slate-900 p-6">
            <p className="text-sm font-bold text-slate-400">
              XP total
            </p>

            <p className="mt-3 text-4xl font-black text-amber-400">
              {xpTotal}
            </p>

            <p className="mt-2 text-sm text-slate-500">
              XP sincronizat cu contul tău
            </p>
          </div>

          <div className="rounded-3xl border border-slate-800 bg-slate-900 p-6">
            <p className="text-sm font-bold text-slate-400">
              Lecții disponibile
            </p>

            <p className="mt-3 text-4xl font-black text-blue-400">
              {totalLectii}
            </p>

            <p className="mt-2 text-sm text-slate-500">
              Modulul 1 + Modulul 2
            </p>
          </div>
        </section>

        <section className="mt-8 rounded-3xl border border-slate-800 bg-slate-900 p-7">
          <div className="flex flex-col gap-6 md:flex-row md:items-center md:justify-between">
            <div className="flex-1">
              <div className="flex items-center justify-between gap-4">
                <div>
                  <p className="text-sm font-black uppercase tracking-wider text-blue-400">
                    Progres total
                  </p>

                  <h2 className="mt-2 text-2xl font-black">
                    {lectiiFinalizate}/
                    {totalLectii} lecții
                  </h2>
                </div>

                <p className="text-2xl font-black">
                  {procentGeneral}%
                </p>
              </div>

              <div className="mt-5 h-4 overflow-hidden rounded-full bg-slate-800">
                <div
                  className="h-full rounded-full bg-blue-500 transition-all"
                  style={{
                    width: `${procentGeneral}%`,
                  }}
                />
              </div>
            </div>
          </div>
        </section>

        {urmatoareaLectie && (
          <section className="mt-8 rounded-3xl border border-blue-500/30 bg-blue-500/5 p-7">
            <p className="text-sm font-black uppercase tracking-wider text-blue-400">
              Continuă de aici
            </p>

            <h2 className="mt-3 text-2xl font-black md:text-3xl">
              {urmatoareaLectie.finalizata
                ? "Ai terminat toate lecțiile construite 🎉"
                : urmatoareaLectie.titlu}
            </h2>

            {!urmatoareaLectie.finalizata && (
              <>
                <p className="mt-3 text-slate-300">
                  Modul{" "}
                  {urmatoareaLectie.modul} •
                  Lecția{" "}
                  {
                    urmatoareaLectie.numarLectie
                  }{" "}
                  din{" "}
                  {
                    urmatoareaLectie.totalLectiiModul
                  }
                </p>

                <a
                  href={urmatoareaLectie.href}
                  className="mt-5 inline-block rounded-xl bg-blue-600 px-6 py-4 font-black transition hover:bg-blue-500"
                >
                  Continuă lecția →
                </a>
              </>
            )}
          </section>
        )}

        <section className="mt-10">
          <p className="text-sm font-black uppercase tracking-wider text-blue-400">
            Progres pe module
          </p>

          <h2 className="mt-2 text-3xl font-black">
            Unde te afli în programă
          </h2>

          <div className="mt-6 grid gap-5 md:grid-cols-2">
            {progresPeModule.map((modul) => (
              <div
                key={modul.modul}
                className="rounded-3xl border border-slate-800 bg-slate-900 p-6"
              >
                <div className="flex items-center justify-between">
                  <div>
                    <p className="text-sm font-bold text-blue-400">
                      MODUL {modul.modul}
                    </p>

                    <p className="mt-1 text-xl font-black">
                      {modul.finalizate}/
                      {modul.total} finalizate
                    </p>
                  </div>

                  <p className="text-2xl font-black">
                    {modul.procent}%
                  </p>
                </div>

                <div className="mt-5 h-3 overflow-hidden rounded-full bg-slate-800">
                  <div
                    className="h-full rounded-full bg-emerald-500 transition-all"
                    style={{
                      width: `${modul.procent}%`,
                    }}
                  />
                </div>
              </div>
            ))}
          </div>
        </section>

        <section className="mt-10 rounded-3xl border border-slate-800 bg-slate-900 p-7">
          <p className="text-sm font-black uppercase tracking-wider text-blue-400">
            Lecțiile tale
          </p>

          <h2 className="mt-2 text-3xl font-black">
            Istoric și progres
          </h2>

          <div className="mt-6 space-y-3">
            {progres.map((lectie) => (
              <a
                key={lectie.id}
                href={lectie.href}
                className="flex items-center gap-4 rounded-2xl border border-slate-800 bg-slate-950 p-4 transition hover:border-slate-700"
              >
                <div
                  className={`flex h-10 w-10 shrink-0 items-center justify-center rounded-xl font-black ${
                    lectie.finalizata
                      ? "bg-emerald-500/10 text-emerald-400"
                      : "bg-slate-900 text-slate-500"
                  }`}
                >
                  {lectie.finalizata
                    ? "✓"
                    : lectie.numarLectie}
                </div>

                <div className="min-w-0 flex-1">
                  <p className="font-bold">
                    {lectie.titlu}
                  </p>

                  <p className="mt-1 text-sm text-slate-500">
                    Modul {lectie.modul} •{" "}
                    {lectie.xp} XP
                  </p>
                </div>

                <div
                  className={`text-sm font-black ${
                    lectie.finalizata
                      ? "text-emerald-400"
                      : "text-slate-500"
                  }`}
                >
                  {lectie.finalizata
                    ? "Finalizată"
                    : "De parcurs"}
                </div>
              </a>
            ))}
          </div>
        </section>

        <div className="mt-8 flex flex-col gap-3 sm:flex-row">
          <a
            href="/programa"
            className="rounded-xl bg-blue-600 px-6 py-4 text-center font-black transition hover:bg-blue-500"
          >
            Vezi programa →
          </a>

          <a
            href="/evaluare"
            className="rounded-xl border border-slate-700 px-6 py-4 text-center font-black transition hover:bg-slate-900"
          >
            Refă evaluarea
          </a>
        </div>
      </div>
    </main>
  );
}